const examples={};
const legacyExamples={"starter": {"hash": "5e8165da", "file": "MojProgram.scl"}, "magnets": {"hash": "43da3114", "file": "FB_AnimacjaMagnesow.scl"}, "timer": {"hash": "6588f62c", "file": "FB_Timer.scl"}, "counter": {"hash": "a51b5233", "file": "FB_Sekwencja.scl"}, "array": {"hash": "e4a9302d", "file": "FB_Tablice.scl"}};
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500);}
function log(message,type='info',line=null){logs.push({message,type,line,time:machine?.now||0});if(logs.length>150)logs.shift();renderLogs();}
function renderLogs(){const el=$('#logs');el.innerHTML=logs.map(l=>`<div class="log-row ${l.type}"><span class="log-time">${(l.time/1000).toFixed(2)} s</span><span class="log-icon">${l.type==='error'?'!':l.type==='warn'?'△':'✓'}</span><span class="log-text">${esc(l.message)}${l.line?` <button class="error-jump" data-line="${l.line}">Linia ${l.line}</button>`:''}</span></div>`).join('');$('#logCount').textContent=logs.length;if(activePanel==='console')el.parentElement.scrollTop=el.parentElement.scrollHeight;}
function setPanel(name){window.dispatchEvent(new Event('scl-open-panel'));activePanel=name;$$('[data-panel]').forEach(b=>{b.classList.toggle('active',b.dataset.panel===name);b.setAttribute('aria-selected',String(b.dataset.panel===name));});for(const n of ['io','trace','console'])$('#'+n+'Panel').classList.toggle('hidden',n!==name);if(name==='trace')drawTrace();}
function inspect(name){activeInspect=name;$$('[data-inspect]').forEach(b=>b.classList.toggle('active',b.dataset.inspect===name));for(const n of ['locals','watches','globals'])$('#'+n+'View').classList.toggle('hidden',n!==name);renderInspector();}
function serialize(){return {version:3,currentExample,filename,code:code.value,drafts,projectFiles,trash,watches,breakpoints:[...breakpoints],globals:$('#globalsJson').value,dt:Number($('#dtSelect').value),speed:Number($('#speedSelect').value)};}
function persist(){clearTimeout(saveTimer);saveTimer=setTimeout(()=>{try{drafts[currentExample]=code.value;localStorage.setItem('scl-lab-project-v3',JSON.stringify(serialize()));$('#saveStatus').innerHTML='<i></i> Zapisano w przeglądarce';lastSaved=Date.now();}catch{$('#saveStatus').textContent='Pobierz projekt, aby zachować pracę';}},400);}
function sourceHash(source){let h=2166136261;for(let i=0;i<source.length;i++)h=Math.imul(h^source.charCodeAt(i),16777619);return (h>>>0).toString(16);}
function loadProject(p){
 if(![1,2,3].includes(p?.version)||typeof p.code!=='string')throw Error('To nie jest plik projektu SCL Lab.');
 drafts={};projectFiles={};trash=p.trash||{};const oldDrafts={...(p.drafts||{})};oldDrafts[p.currentExample||'custom']=p.code;
 for(const [id,source]of Object.entries(oldDrafts)){if(typeof source!=='string')continue;const legacy=legacyExamples[id];if(legacy&&sourceHash(source)===legacy.hash)continue;const target=legacy?'user_saved_'+id:id==='custom'?'user_imported':id;drafts[target]=source;projectFiles[target]=p.projectFiles?.[id]||legacy?.file||'Program.scl';}
 const activeLegacy=legacyExamples[p.currentExample];if(activeLegacy&&sourceHash(p.code)===activeLegacy.hash){currentExample='user_default';filename='MojProgram.scl';code.value=drafts.user_default??blankSource;watches=[];breakpoints=new Set();}
 else{currentExample=activeLegacy?'user_saved_'+p.currentExample:p.currentExample==='custom'?'user_imported':p.currentExample||'user_default';filename=p.filename||'Program.scl';code.value=p.code;watches=Array.isArray(p.watches)?p.watches.slice(0,20):[];breakpoints=new Set((p.breakpoints||[]).filter(Number.isInteger));}
 drafts[currentExample]=code.value;projectFiles[currentExample]=filename;$('#globalsJson').value=p.globals||'{}';
 for(const [id,key]of [['dtSelect','dt'],['speedSelect','speed']])if(p[key]!==undefined)$('#'+id).value=String(p[key]);
}
function restore(){try{const p=JSON.parse(localStorage.getItem('scl-lab-project-v3')||localStorage.getItem('scl-lab-project-v2')||localStorage.getItem('scl-lab-project-v1')||'null');if(!p)return false;loadProject(p);return true;}catch{return false;}}

function highlight(){const text=code.value;let result='',last=0;const re=/(\/\*[\s\S]*?\*\/|\(\*[\s\S]*?\*\)|\/\/[^\n]*|"(?:[^"]|"")*"|'(?:[^']|'')*'|\b(?:LTIME|TIME|LT|T)#[+-]?(?:\d+(?:\.\d+)?(?:ms|us|ns|d|h|m|s))+|#[\w\u00c0-\u024f]+|\b[A-Za-z_][\w]*\b|\b\d+(?:\.\d+)?)/gi;
 const kw=new Set('FUNCTION_BLOCK END_FUNCTION_BLOCK FUNCTION END_FUNCTION ORGANIZATION_BLOCK END_ORGANIZATION_BLOCK BEGIN VAR VAR_INPUT VAR_OUTPUT VAR_IN_OUT VAR_TEMP VAR_STAT VAR_CONSTANT END_VAR IF THEN ELSIF ELSE END_IF CASE OF END_CASE FOR TO BY DO END_FOR WHILE END_WHILE REPEAT UNTIL END_REPEAT EXIT CONTINUE RETURN AND OR NOT XOR MOD DIV ARRAY STRUCT END_STRUCT TRUE FALSE VERSION'.split(' '));const types=new Set('BOOL INT DINT SINT UINT USINT UDINT LINT REAL LREAL STRING CHAR TIME LTIME WORD BYTE DWORD TON_TIME TOF_TIME TP_TIME IEC_TIMER R_TRIG F_TRIG'.split(' '));
 for(const m of text.matchAll(re)){result+=esc(text.slice(last,m.index));let t=m[0],cls=t.startsWith('//')||t.startsWith('/*')||t.startsWith('(*')?'comment':t[0]==='"'||t[0]==="'"?'string':t[0]==='#'?'local':/^(LTIME|TIME|LT|T)#/i.test(t)?'time':/^\d/.test(t)?'number':kw.has(t.toUpperCase())?'keyword':types.has(t.toUpperCase())?'type':null;result+=cls?`<span class="tok-${cls}">${esc(t)}</span>`:esc(t);last=m.index+t.length;}result+=esc(text.slice(last));$('#highlight').innerHTML=result+'\n';renderGutter();syncScroll();cursor();}
function renderGutter(){const total=code.value.split('\n').length;const active=errorLine||machine?.nextLine||machine?.lastLine;$('#gutter').innerHTML='<div class="gutter-inner">'+Array.from({length:total},(_,i)=>{const n=i+1;return `<button class="gutter-line ${breakpoints.has(n)?'break':''} ${n===active?(errorLine?'error':'current'):''}" data-line="${n}" title="${n===machine?.nextLine?'Następna instrukcja — jeszcze niewykonana. ':''}${breakpoints.has(n)?'Usuń':'Dodaj'} punkt przerwania w linii ${n}" aria-label="Linia ${n}${breakpoints.has(n)?', punkt przerwania':''}">${n}</button>`;}).join('')+'</div>';$('#breakpointCount').textContent=breakpoints.size+' '+(breakpoints.size===1?'punkt przerwania':'punktów przerwania');syncScroll();}
function editorLineHeight(){return parseFloat(getComputedStyle(code).lineHeight)||24;}
function syncScroll(){runtimeMonitor?.render(machine,{running,dirty,error:!!errorLine});const h=$('#highlight');h.scrollTop=code.scrollTop;h.scrollLeft=code.scrollLeft;const g=$('.gutter-inner');if(g)g.style.transform=`translateY(${-code.scrollTop}px)`;const line=errorLine||machine?.nextLine||machine?.lastLine;const el=$('#executionHighlight');if(line){el.style.display='block';el.style.top=((line-1)*editorLineHeight()-code.scrollTop)+'px';el.classList.toggle('error',!!errorLine);}else el.style.display='none';}
function goLine(line){const lines=code.value.split('\n'),pos=lines.slice(0,line-1).reduce((n,s)=>n+s.length+1,0);code.focus();code.setSelectionRange(pos,pos);code.scrollTop=Math.max(0,(line-1)*editorLineHeight()-code.clientHeight*.35);syncScroll();cursor();}
function cursor(){const before=code.value.slice(0,code.selectionStart).split('\n');$('#cursorStatus').textContent='Ln '+before.length+', Kol '+(before.at(-1).length+1);}
function markDirty(){pause(false);dirty=true;errorLine=null;$('#dirtyMark').textContent='•';$('#compileStatus').innerHTML='<i style="background:#e4bd78"></i> Kod zmieniony';drafts[currentExample]=code.value;persist();highlight();renderStatus();}
function compileCode({quiet=false}={}){pause(false);try{const extra=globalsFromJSON($('#globalsJson').value);const globals=Object.create(null);Object.assign(globals,extra);machine=compile(code.value,{globals,dt:Number($('#dtSelect').value)});machine.onScan=()=>{const values={};for(const w of watches){try{const v=machine.read(w).v;if(typeof v==='boolean'||typeof v==='number')values[w]=Number(v);}catch{}}history.push({time:machine.now,values});if(history.length>160)history.shift();};history=[];dirty=false;errorLine=null;skipBreakpoint=null;$('#dirtyMark').textContent='';$('#compileStatus').innerHTML='<i></i> Składnia i nazwy OK';if(!quiet)log('Sprawdzono '+machine.program.name+'. Pamięć instancji wyzerowana.');renderAll();persist();return true;}catch(e){handleError(e);return false;}}
function handleError(e){pause(false);errorLine=e.line||1;$('#compileStatus').innerHTML='<i style="background:#ed817e"></i> Błąd w linii '+errorLine;log(e.message,'error',errorLine);renderStatus();renderGutter();setPanel('console');goLine(errorLine);toast('Linia '+errorLine+': '+e.message);}
function ensure(){if(dirty||!machine||errorLine)return compileCode();return true;}
function pause(announce=true){const was=running;running=false;clearInterval(interval);interval=null;if(was&&announce)log('Pauza. Pamięć i czas symulacji zachowane.');if(was)renderAll();else renderStatus();}
function run(){if(running){pause();return;}if(!ensure()||!flushEditedValues())return;running=true;skipBreakpoint=machine.nextLine;log('Uruchomiono cykliczne wykonanie. Cykl: '+machine.dt+' ms.');restartInterval();renderStatus();}
function restartInterval(){clearInterval(interval);if(!running)return;const dt=machine.dt,speed=Number($('#speedSelect').value),period=Math.max(16,dt/speed),scansPerTick=Math.max(1,Math.round(period*speed/dt));interval=setInterval(()=>{try{let steps=0;for(let s=0;s<scansPerTick&&running;s++){const initial=machine.scans;while(machine.scans===initial&&running){if(!machine.generator)machine.beginScan();if(machine.scans!==initial)break;const line=machine.nextLine;if(breakpoints.has(line)&&skipBreakpoint!==line){pause(false);log('Punkt przerwania w linii '+line+'.','info',line);goLine(line);renderAll();return;}skipBreakpoint=null;machine.step();if(++steps>=12000)break;}if(steps>=12000)break;}if(Date.now()-renderTick>75){renderAll();renderTick=Date.now();}}catch(e){handleError(e);}},period);}
function stepInstruction(){pause(false);if(!ensure()||!flushEditedValues())return;try{machine.step();errorLine=null;renderAll();if(machine.nextLine)goLine(machine.nextLine);}catch(e){handleError(e);}}
function stepScan(){pause(false);if(!ensure()||!flushEditedValues())return;try{machine.scan();errorLine=null;renderAll();}catch(e){handleError(e);}}
function renderStatus(){runtimeMonitor?.render(machine,{running,dirty,error:!!errorLine});const state=errorLine?'Błąd':dirty?'Kod zmieniony':running?'Wykonywanie cykliczne':machine?.nextLine?'Pauza · następna linia '+machine.nextLine:'Zatrzymany';$('#executionStatus').textContent=state;$('#executionDot').className='status-dot'+(running?' running':errorLine?' error':'');$('#runIcon').textContent=running?'Ⅱ':'▶';$('#runLabel').textContent=running?'Pauza':'Uruchom';$('#livePill').innerHTML='<i></i> '+(running?'RUN':errorLine?'BŁĄD':'PAUZA');$('#livePill').classList.toggle('running',running);$('#scanMetric').textContent=(machine?.scans||0).toLocaleString('pl');const time=machine?.now||0;$('#timeMetric').innerHTML=time>=1000?(time/1000).toFixed(2)+'<span> s</span>':time+'<span> ms</span>';}
function formatValue(v,t){if(typeof v==='object')return '…';if(t==='TIME'||t==='LTIME')return 'T#'+v+'ms';if(typeof v==='boolean')return v?'TRUE':'FALSE';return String(v);}
function valueControl(path,type,value){const kind=type.name||type.kind;if(type.kind!=='scalar')return `<button class="expand-button" data-expand="${esc(path)}">${expanded.has(path)?'▾':'▸'}</button>`;if(kind==='BOOL')return `<button class="bool-toggle ${value?'on':''}" data-toggle="${esc(path)}" aria-label="Przełącz ${esc(path)}">${value?'TRUE':'FALSE'}</button>`;return `<input class="value-input" aria-label="Wartość ${esc(path)}" data-value="${esc(path)}" data-type="${esc(kind)}" value="${esc(formatValue(value,kind))}" title="Enter zatwierdza, Escape anuluje">`;}
function renderRow(name,type,value,path,depth=0){let children='';if(expanded.has(path)&&depth<4){if(type.kind==='struct'){children=type.fields.map(f=>renderRow(f.name,f.type,value[f.name],path+'.'+f.name,depth+1)).join('');}else if(type.kind==='timer'){children=['IN','PT','Q','ET',...(type.name.includes('TRIG')?['CLK']:[])].map(f=>renderRow(f,{kind:'scalar',name:['IN','Q','CLK'].includes(f)?'BOOL':'TIME'},value[f],path+'.'+f,depth+1)).join('');}else if(type.kind==='array'){const rec=(dims,v,prefix)=>{const[lo,hi]=dims[0];const max=Math.min(hi,lo+11);let out='';for(let i=lo;i<=max;i++){if(dims.length===1){const ix=[...prefix,i];out+=renderRow('['+ix.join(',')+']',type.of,v[i],path+'['+ix.join(',')+']',depth+1);}else out+=rec(dims.slice(1),v[i],[...prefix,i]);}if(hi>max)out+='<div class="array-note">Dalsze elementy dodaj do obserwowanych.</div>';return out;};children=rec(type.dims,value,[]);}}
 const typeLabel=type.kind==='array'?'ARRAY ['+type.dims.map(d=>d.join('..')).join(',')+']':type.name||'STRUCT';return `<div class="var-row"><div class="var-left" ${type.kind!=='scalar'?`data-expand="${esc(path)}"`:''} title="${esc(path)}"><span class="var-name">${esc(name)}</span><div class="var-type">${esc(typeLabel)}</div></div><div class="var-value"><button class="watch-add" data-watch="${esc(path)}" title="Dodaj do obserwowanych" aria-label="Obserwuj ${esc(path)}">＋</button>${valueControl(path,type,value)}</div></div>${children?'<div class="nested">'+children+'</div>':''}`;
}
function renderInspector(){if(!machine)return;const editing=document.activeElement?.matches('.value-input');if(activeInspect==='locals'&&!editing){const filter=$('#variableFilter').value.toLowerCase();let html='';for(const [section,label]of [['VAR_INPUT','WEJŚCIA'],['VAR_OUTPUT','WYJŚCIA'],['VAR_IN_OUT','IN_OUT · LOKALNA KOPIA'],['VAR','PAMIĘĆ STATYCZNA'],['VAR_STAT','PAMIĘĆ STATYCZNA'],['VAR_TEMP','TYMCZASOWE'],['VAR_CONSTANT','STAŁE']]){const names=Object.keys(machine.locals).filter(n=>machine.sections[n]===section&&n.toLowerCase().includes(filter));if(names.length){html+='<div class="var-group-label">'+label+'</div>';html+=names.map(n=>renderRow(n,machine.schemas[n],machine.locals[n],'#'+n)).join('');}}$('#variables').innerHTML=html||'<div class="empty-inspector">Brak zmiennych. Dodaj deklaracje VAR do programu.</div>';}
 if(activeInspect==='watches'&&!editing){$('#watches').innerHTML=watches.map(w=>{try{const r=machine.resolve(machine.ref(w)),v=r.obj[r.key];return `<div class="watch-item"><div class="watch-top"><span class="watch-path">${esc(w)}</span><button class="remove-watch" data-remove="${esc(w)}" aria-label="Usuń ${esc(w)}">×</button></div><div class="watch-bottom"><span class="var-type">${esc(r.type.name||r.type.kind)}</span>${valueControl(w,r.type,v)}</div></div>`;}catch(e){return `<div class="watch-item"><div class="watch-top"><span class="watch-path">${esc(w)}</span><button class="remove-watch" data-remove="${esc(w)}">×</button></div><span class="watch-error">${esc(e.message)}</span></div>`;}}).join('')||'<div class="empty-inspector">Dodaj sygnał, który chcesz śledzić.</div>';}
 $('#watchCount').textContent=watches.length;
}
function addWatch(w){if(!machine&&!ensure())return;try{machine.read(w);if(!watches.includes(w)){watches.push(w);if(watches.length>20)watches.shift();log('Dodano obserwację: '+w);persist();}inspect('watches');updateTraceSelect();}catch(e){toast(e.message);}}
function updateTraceSelect(){const select=$('#traceSelect'),old=select.value;select.innerHTML=watches.map(w=>`<option value="${esc(w)}">${esc(w)}</option>`).join('');if(watches.includes(old))select.value=old;}

function drawTrace(){if(activePanel!=='trace')return;const c=$('#traceCanvas'),ctx=c.getContext('2d'),rect=c.getBoundingClientRect(),dpr=window.devicePixelRatio||1;c.width=Math.max(1,rect.width*dpr);c.height=165*dpr;ctx.scale(dpr,dpr);const width=rect.width,height=165;ctx.clearRect(0,0,width,height);const key=$('#traceSelect').value;const data=history.filter(p=>Object.hasOwn(p.values,key));$('#traceEmpty').classList.toggle('hidden',data.length>1);ctx.font='8px Consolas,monospace';ctx.fillStyle='#94a6b1';const vals=data.map(p=>p.values[key]);let lo=Math.min(0,...vals),hi=Math.max(1,...vals);if(lo===hi)hi=lo+1;let left=40,right=width-14,top=10,bottom=135;ctx.lineWidth=1;for(let i=0;i<4;i++){let y=top+(bottom-top)*i/3;ctx.strokeStyle='#3a414b';ctx.beginPath();ctx.moveTo(left,y);ctx.lineTo(right,y);ctx.stroke();let label=hi-(hi-lo)*i/3;ctx.fillText(label.toFixed(hi-lo>10?0:1),2,y+3);}if(data.length<2)return;const x=i=>left+(right-left)*i/(data.length-1),y=v=>bottom-(v-lo)/(hi-lo)*(bottom-top);ctx.beginPath();ctx.moveTo(x(0),bottom);ctx.lineTo(x(0),y(vals[0]));for(let i=1;i<data.length;i++){ctx.lineTo(x(i),y(vals[i-1]));ctx.lineTo(x(i),y(vals[i]));}ctx.lineTo(right,bottom);ctx.closePath();ctx.fillStyle='#2ba48512';ctx.fill();ctx.beginPath();ctx.moveTo(x(0),y(vals[0]));for(let i=1;i<data.length;i++){ctx.lineTo(x(i),y(vals[i-1]));ctx.lineTo(x(i),y(vals[i]));}ctx.strokeStyle='#34977c';ctx.lineWidth=1.6;ctx.stroke();ctx.fillStyle='#91a4af';ctx.fillText((data[0].time/1000).toFixed(2)+' s',left,156);ctx.textAlign='right';ctx.fillText((data.at(-1).time/1000).toFixed(2)+' s',right,156);ctx.textAlign='left';}
function renderAll(){renderStatus();renderInspector();renderIO();renderGutter();drawTrace();}
function renderExamples(){renderUserProjects();}
function download(name,data,type='text/plain'){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function editValue(path,value){if(!machine)return;try{machine.write(path,value);renderAll();}catch(e){toast(e.message);renderAll();}}

function renderIO(){if(!machine)return;if(document.activeElement?.matches('#ioPanel [data-value]'))return;const io=ioSignals(machine);$('#ioCounts').textContent=io.inputs.length+' wejść · '+io.outputs.length+' wyjść · z Twoich deklaracji';$('#ioLimit').textContent=io.truncated?'Podgląd do 80 sygnałów':'';
 const renderSignal=(s,input)=>{let control;if(input){control=valueControl(s.path,s.type,s.value);if(s.type.name==='BOOL')control+=`<button class="io-pulse" data-pulse="${esc(s.path)}" aria-label="Impuls na jeden cykl ${esc(s.path)}" title="TRUE przez jeden pełny cykl PLC">1 cykl ↥</button>`;}else if(s.type.name==='BOOL')control=`<span class="io-light ${s.value?'on':''}" aria-label="Wyjście ${esc(s.name)}: ${s.value?'TRUE':'FALSE'}"><i></i>${s.value?'TRUE':'FALSE'}</span>`;else control=`<output class="io-output-value" aria-label="Wyjście ${esc(s.name)}">${esc(formatValue(s.value,s.type.name))}</output>`;
 return `<div class="io-signal"><div class="io-signal-name"><strong title="${esc(s.path)}">${esc(s.name)}</strong><small>${esc(s.type.name)}</small></div><div class="io-signal-controls">${control}</div></div>`;};
 $('#ioInputs').innerHTML=io.inputs.map(s=>renderSignal(s,true)).join('')||'<div class="io-empty">Dodaj własne wejście w sekcji VAR_INPUT.<button data-add-section="VAR_INPUT">＋ Dodaj wejście</button></div>';
 $('#ioOutputs').innerHTML=io.outputs.map(s=>renderSignal(s,false)).join('')||'<div class="io-empty">Zadeklaruj wyjście w VAR_OUTPUT, aby obserwować wynik.<button data-add-section="VAR_OUTPUT">＋ Dodaj wyjście</button></div>';
}
function decodeInputValue(input){const type=input.dataset.type;let value=input.value.trim();if(type==='TIME'||type==='LTIME'){const p=new Parser(value);value=machine.eval(p.expression()).v;p.need('EOF');}else if(!['STRING','CHAR'].includes(type)){value=Number(value);if(input.value.trim()===''||!Number.isFinite(value))throw new Error('Wpisz poprawną liczbę.');}return value;}
function flushEditedValues(){if(!machine)return true;try{let changed=false;for(const input of $$('[data-value]'))if(input.value!==input.defaultValue){machine.write(input.dataset.value,decodeInputValue(input));changed=true;}if(changed){document.activeElement?.blur();renderAll();}return true;}catch(er){toast(er.message);return false;}}
function commitValueInput(input){const type=input.dataset.type;let value=input.value.trim();if(type==='TIME'||type==='LTIME'){try{const p=new Parser(value);value=machine.eval(p.expression()).v;p.need('EOF');}catch{toast('Wpisz czas np. T#200ms lub T#1s');input.blur();renderAll();return;}}else if(!['STRING','CHAR'].includes(type)){value=Number(value);if(input.value.trim()===''||!Number.isFinite(value)){toast('Wpisz poprawną liczbę.');input.blur();renderAll();return;}}const path=input.dataset.value;input.blur();editValue(path,value);}
function pulseInput(path){if(!ensure()||!flushEditedValues())return;try{if(machine.generator)machine.scan();const value=machine.read(path).v;if(value===true){toast('Najpierw ustaw wejście na FALSE, aby podać impuls.');return;}machine.write(path,true);machine.scan();machine.write(path,false);renderAll();log('Impuls '+path+': TRUE przez jeden cykl PLC.');}catch(er){handleError(er);}}
function openVariable(section='VAR_INPUT'){pause(false);$('#declSection').value=section;$('#declName').value='';$('#declError').textContent='';$('#declArray').checked=false;updateDeclarationPreview();$('#variableDialog').showModal();$('#declName').focus();}
function updateDeclarationPreview(){const array=$('#declArray').checked,type=$('#declType').value,timer=type.endsWith('_TIME')||type.endsWith('_TRIG');$('#arrayBounds').classList.toggle('hidden',!array);$('#declInitial').disabled=array||timer;const name=$('#declName').value.trim()||'NowaZmienna';const spec=array?'Array['+$('#declLower').value+'..'+$('#declUpper').value+'] of '+type:type;const initial=!array&&!timer&&$('#declInitial').value.trim()?' := '+$('#declInitial').value.trim():'';$('#declPreview').textContent=name+' : '+spec+initial+';';$('#declError').textContent='';}
function renderUserProjects(){const ids=Object.keys(drafts);$('#userProjects').innerHTML='<div class="section-label">MOJE PROGRAMY <span>'+ids.length+'</span></div>'+ids.map(id=>`<div class="project-row"><button class="user-project-button ${currentExample===id?'active':''}" data-project="${esc(id)}" title="${esc(projectFiles[id]||'Program.scl')}">S · ${esc(projectFiles[id]||'Program.scl')}</button><button class="delete-project" data-delete-project="${esc(id)}" aria-label="Usuń ${esc(projectFiles[id]||'Program.scl')}" title="Przenieś do kosza">×</button></div>`).join('')+'<div class="trash-heading">KOSZ · '+Object.keys(trash).length+'</div>'+Object.entries(trash).map(([id,p])=>`<div class="project-row"><span class="trashed-name">${esc(p.filename)}</span><button class="restore-project" data-restore-project="${esc(id)}" title="Przywróć program" aria-label="Przywróć ${esc(p.filename)}">↶</button></div>`).join('');}
function deleteProgram(id){pause(false);if(id===currentExample)drafts[id]=code.value;if(!Object.hasOwn(drafts,id))return;const item={code:drafts[id],filename:projectFiles[id]||'Program.scl'};trash[id]=item;delete drafts[id];delete projectFiles[id];if(id===currentExample){const next=Object.keys(drafts)[0];if(next){currentExample=next;filename=projectFiles[next]||'Program.scl';code.value=drafts[next];}else{currentExample='user_'+Date.now().toString(36);filename='MojProgram.scl';code.value=blankSource;drafts[currentExample]=code.value;projectFiles[currentExample]=filename;}watches=[];breakpoints.clear();$('#fileName').textContent=filename;highlight();updateTraceSelect();compileCode({quiet:true});}renderUserProjects();persist();toast('Program przeniesiony do kosza. Możesz go przywrócić.');}
function restoreProgram(id){const item=trash[id];if(!item)return;let target=Object.hasOwn(drafts,id)?'user_'+Date.now().toString(36):id;drafts[target]=item.code;projectFiles[target]=item.filename;delete trash[id];renderUserProjects();persist();toast('Przywrócono '+item.filename);}
function formatEditor(announce=true){if(running)pause(false);const focused=document.activeElement===code;const old=code.value,next=formatSCL(old);if(next!==old){const line=old.slice(0,code.selectionStart).split('\n').length;code.value=next;markDirty();if(focused)goLine(line);}if(announce)toast('Wyrównano wcięcia kodu.');}

function newProgram(){pause(false);drafts[currentExample]=code.value;projectFiles[currentExample]=filename;currentExample='user_'+Date.now().toString(36);filename='Program_'+(Object.keys(drafts).filter(id=>id.startsWith('user_')).length+1)+'.scl';projectFiles[currentExample]=filename;code.value=blankSource;drafts[currentExample]=code.value;watches=[];breakpoints.clear();expanded.clear();$('#fileName').textContent=filename;code.setSelectionRange(0,0);code.scrollTop=0;renderExamples();highlight();updateTraceSelect();compileCode();inspect('locals');setPanel('io');persist();toast('Nowy program — dodaj zmienne i napisz kod.');}
function openUserProject(id){pause(false);drafts[currentExample]=code.value;projectFiles[currentExample]=filename;currentExample=id;filename=projectFiles[id]||'Program.scl';code.value=drafts[id]??blankSource;watches=[];breakpoints.clear();expanded.clear();$('#fileName').textContent=filename;code.setSelectionRange(0,0);code.scrollTop=0;renderExamples();highlight();updateTraceSelect();compileCode();inspect('locals');setPanel('io');persist();}

function wire(){
 setupAssist(code);
 runtimeMonitor=setupInlineMonitor(code,addWatch);
 $('#formatBtn').onclick=()=>formatEditor();
 try{$('#autoFormat').checked=localStorage.getItem('scl-auto-format')==='true';}catch{}
 $('#autoFormat').onchange=()=>{try{localStorage.setItem('scl-auto-format',String($('#autoFormat').checked));}catch{}};
 $('#functionsBtn').onclick=()=>{$('#functionList').textContent=supportedFunctions.join(' · ');$('#functionsDialog').showModal();};$('#closeFunctions').onclick=()=>$('#functionsDialog').close();
 code.addEventListener('keydown',e=>{if(e.shiftKey&&e.altKey&&e.key.toLowerCase()==='f'){e.preventDefault();e.stopImmediatePropagation();formatEditor();}},true);
 code.addEventListener('blur',()=>{if($('#autoFormat').checked)formatEditor(false);});
 code.addEventListener('paste',()=>{setTimeout(()=>{if($('#autoFormat').checked)formatEditor(false);},0);});

 code.addEventListener('input',markDirty);code.addEventListener('scroll',syncScroll);code.addEventListener('click',cursor);code.addEventListener('keyup',cursor);code.addEventListener('keydown',e=>{if(e.key==='Tab'){e.preventDefault();const start=code.selectionStart,end=code.selectionEnd;code.setRangeText('    ',start,end,'end');markDirty();}if(e.key==='Enter'&&!e.ctrlKey&&!e.metaKey){e.preventDefault();let before=code.value.slice(0,code.selectionStart),indent=before.split('\n').at(-1).match(/^\s*/)[0];code.setRangeText('\n'+indent,code.selectionStart,code.selectionEnd,'end');markDirty();}});
 $('#gutter').addEventListener('click',e=>{let b=e.target.closest('[data-line]');if(!b)return;let n=Number(b.dataset.line);if(breakpoints.has(n))breakpoints.delete(n);else breakpoints.add(n);renderGutter();persist();});
 $('#runBtn').onclick=run;$('#stepBtn').onclick=stepInstruction;$('#scanBtn').onclick=stepScan;$('#compileBtn').onclick=()=>compileCode();$('#resetBtn').onclick=()=>{if(compileCode({quiet:true})){log('Wyzerowano pamięć, model siłowników i czas symulacji.');toast('Symulator wyzerowany');}};
 $('#dtSelect').onchange=()=>{if(machine)machine.dt=Number($('#dtSelect').value);restartInterval();persist();};$('#speedSelect').onchange=restartInterval;
 $('#newBtn').onclick=newProgram;
 $$('[data-panel]').forEach(b=>b.onclick=()=>setPanel(b.dataset.panel));$$('[data-inspect]').forEach(b=>b.onclick=()=>inspect(b.dataset.inspect));$('#variableFilter').oninput=renderInspector;
 document.addEventListener('click',e=>{let b=e.target.closest('[data-toggle]');if(b){try{const v=machine.read(b.dataset.toggle).v;editValue(b.dataset.toggle,!v);}catch(er){toast(er.message);}return;}b=e.target.closest('[data-expand]');if(b){let p=b.dataset.expand;if(expanded.has(p))expanded.delete(p);else expanded.add(p);renderInspector();return;}b=e.target.closest('[data-watch]');if(b){addWatch(b.dataset.watch);return;}b=e.target.closest('[data-remove]');if(b){watches=watches.filter(w=>w!==b.dataset.remove);renderInspector();updateTraceSelect();persist();}});
 document.addEventListener('keydown',e=>{const input=e.target.closest('[data-value]');if(!input)return;if(e.key==='Escape'){input.blur();renderAll();}if(e.key==='Enter'){e.preventDefault();commitValueInput(input);}});
 document.addEventListener('change',e=>{const input=e.target.closest('[data-value]');if(input)commitValueInput(input);});
 $('#ioPanel').addEventListener('click',e=>{const p=e.target.closest('[data-pulse]');if(p)pulseInput(p.dataset.pulse);const add=e.target.closest('[data-add-section]');if(add)openVariable(add.dataset.addSection);});
 $('#addIOBtn').onclick=()=>openVariable('VAR_INPUT');$('#addVariableBtn').onclick=()=>openVariable('VAR_INPUT');$('#closeVariable').onclick=()=>$('#variableDialog').close();
 $('#declType').onchange=()=>{const type=$('#declType').value;$('#declInitial').value=type==='BOOL'?'FALSE':type==='TIME'?'T#0ms':type==='STRING'?"''":type.endsWith('_TIME')||type.endsWith('_TRIG')?'':type==='REAL'||type==='LREAL'?'0.0':'0';updateDeclarationPreview();};
 for(const id of ['declName','declSection','declInitial','declArray','declLower','declUpper'])$('#'+id).addEventListener('input',updateDeclarationPreview);
 $('#variableForm').onsubmit=e=>{e.preventDefault();try{const source=insertDeclaration(code.value,{name:$('#declName').value,section:$('#declSection').value,type:$('#declType').value,initial:$('#declInitial').value,array:$('#declArray').checked,lower:$('#declLower').value,upper:$('#declUpper').value});code.value=source;drafts[currentExample]=source;highlight();$('#variableDialog').close();compileCode();inspect('locals');setPanel('io');toast('Dodano zmienną '+$('#declName').value);persist();}catch(er){$('#declError').textContent=er.message;}};
 $('#userProjects').onclick=e=>{let b=e.target.closest('[data-delete-project]');if(b){deleteProgram(b.dataset.deleteProject);return;}b=e.target.closest('[data-restore-project]');if(b){restoreProgram(b.dataset.restoreProject);return;}b=e.target.closest('[data-project]');if(b)openUserProject(b.dataset.project);};
 $('#watchForm').onsubmit=e=>{e.preventDefault();const v=$('#watchInput').value.trim();if(v){addWatch(v);$('#watchInput').value='';}};$('#applyGlobals').onclick=()=>compileCode();$('#globalsJson').oninput=()=>{dirty=true;pause(false);persist();$('#compileStatus').innerHTML='<i style="background:#e4bd78"></i> Dane DB zmienione';};

 $('#traceSelect').onchange=drawTrace;window.addEventListener('resize',drawTrace);window.addEventListener('scl-layout',()=>{syncScroll();drawTrace();});$('#clearLogs').onclick=()=>{logs=[];renderLogs();};$('#logs').onclick=e=>{const b=e.target.closest('[data-line]');if(b)goLine(Number(b.dataset.line));};$('#clearBreakpoints').onclick=()=>{breakpoints.clear();renderGutter();persist();toast('Usunięto punkty przerwania');};
 for(const id of ['helpBtn','scopeBtn'])$('#'+id).onclick=()=>$('#helpDialog').showModal();$('#closeHelp').onclick=()=>$('#helpDialog').close();$('#helpDialog').onclick=e=>{if(e.target===e.currentTarget){const r=e.currentTarget.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.currentTarget.close();}};$('#editorTab').onclick=()=>code.focus();$('.brand').onclick=e=>{e.preventDefault();code.focus();};
 $('#exportBtn').onclick=()=>{if($('#autoFormat').checked)formatEditor(false);download(filename,code.value);toast('Pobrano plik SCL');};$('#downloadProject').onclick=()=>{if($('#autoFormat').checked)formatEditor(false);download('scl-lab-projekt.json',JSON.stringify(serialize(),null,2),'application/json');toast('Pobrano projekt z kodem i ustawieniami');};$('#importBtn').onclick=()=>$('#fileInput').click();$('#fileInput').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>1000000){toast('Maksymalny rozmiar pliku: 1 MB');return;}try{const text=await f.text();pause(false);drafts[currentExample]=code.value;if(f.name.toLowerCase().endsWith('.json')){loadProject(JSON.parse(text));}else{currentExample='user_'+Date.now().toString(36);filename=f.name;projectFiles[currentExample]=filename;code.value=text;drafts[currentExample]=text;watches=[];breakpoints.clear();}$('#fileName').textContent=filename;renderExamples();highlight();updateTraceSelect();compileCode();setPanel('io');persist();toast('Wczytano '+f.name);}catch(er){toast(er.message);}e.target.value='';};
 document.addEventListener('keydown',e=>{if(document.querySelector('dialog[open]'))return;if(e.key==='F5'){e.preventDefault();run();}if(e.key==='F10'){e.preventDefault();if(e.shiftKey)stepScan();else stepInstruction();}if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();compileCode();}if(e.key.toLowerCase()==='s'&&(e.ctrlKey||e.metaKey)){e.preventDefault();if($('#autoFormat').checked)formatEditor(false);download(filename,code.value);}});
 window.addEventListener('beforeunload',()=>{try{drafts[currentExample]=code.value;localStorage.setItem('scl-lab-project-v3',JSON.stringify(serialize()));}catch{}});
}
async function init(){
 const restored=restore();if(!restored){code.value=blankSource;watches=[];drafts[currentExample]=code.value;projectFiles[currentExample]=filename;}
 $('#fileName').textContent=filename;code.setSelectionRange(0,0);code.scrollTop=0;renderExamples();highlight();wire();updateTraceSelect();loaded=true;compileCode({quiet:true});log('SCL Lab gotowy. Napisz swój kod, ustaw wejścia i wykonaj cykl PLC.');log('Interpreter wybranego zakresu SCL. Ostateczną zgodność sprawdź w TIA Portal.','warn');window.SCLLab={get machine(){return machine;},compile:compileCode,step:stepInstruction,scan:stepScan,pause};
}
init();
